function renderMonthCards(){const host=document.querySelector('#month-cards');host.innerHTML='';campaigns.forEach(c=>{const button=document.createElement('button');button.className=`month-card${c.key===startInput.value.slice(0,7)?' active':''}${c.ready?'':' pending'}`;button.disabled=!c.ready;button.innerHTML=c.ready?`<img src="${c.cover}" alt=""><span class="month-card-shade"></span><span class="month-card-copy"><small>READY · ${c.count}/${c.target} POSTS</small><strong>${c.label}</strong><em>Open collection →</em></span>`:`<span class="month-card-empty">+</span><span class="month-card-copy"><small>AWAITING POSTERS · ${c.count}/${c.target}</small><strong>${c.label}</strong><em>${c.note}</em></span>`;button.addEventListener('click',()=>{startInput.value=c.startDate;posters=c.posts;captions=c.captions;activeFilter='all';collectionContent.hidden=false;document.querySelectorAll('.filter').forEach(filter=>filter.classList.toggle('active',filter.dataset.filter==='all'));document.querySelector('#selected-month').textContent=c.label;renderMonthCards();render();document.querySelector('.schedule-bar').scrollIntoView({behavior:'smooth'})});host.append(button)})}
function dateFor(i){const d=new Date(`${startInput.value}T12:00:00`);d.setDate(d.getDate()+i);return d}
function render(filter=activeFilter){
 activeFilter=filter;visible=[];calendar.innerHTML='';const grid=document.createElement('div');grid.className='grid';
 posters.forEach((p,i)=>{if(filter!=='all'&&p.category!==filter)return;visible.push(i);const d=dateFor(i),card=document.createElement('article');card.className='card';card.innerHTML=`<button class="poster-button" data-index="${i}" aria-label="View ${p.title} poster scheduled for ${dayFmt.format(d)}"><span class="date-badge"><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('en-IN',{weekday:'short'}).toUpperCase()}</span></span><img src="${p.src}" alt="Motivational health poster photographed at ${p.title}" loading="lazy"></button><button class="card-copy" type="button" data-index="${i}" aria-label="Copy caption and download ${p.title} poster"><span aria-hidden="true">⇩</span> Download + copy</button><div class="meta"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h3>${p.title}</h3><p>${dayFmt.format(d)} · ${p.category==='heritage'?'Heritage':p.category==='hills'?'Hills & forest':'Water & coast'}</p></div></div>`;grid.append(card)});
 calendar.append(grid);
 document.querySelectorAll('.filter').forEach(button=>{const count=button.dataset.filter==='all'?posters.length:posters.filter(p=>p.category===button.dataset.filter).length;button.querySelector('span').textContent=count});document.querySelector('#empty').hidden=visible.length>0;document.querySelector('#schedule-range').textContent=`${rangeFmt.format(dateFor(0))} — ${rangeFmt.format(dateFor(posters.length-1))}`;document.querySelector('#schedule-note').textContent=`One Instagram post every day for ${posters.length} days`;
}
function setViewerBrand(mode){const doctor=mode==='doctor';viewerAvatar.src=viewerCaptionAvatar.src=doctor?'assets/profile.png':'assets/logos/fofitos.png';viewerAvatar.alt=doctor?'Doctor Farmer':'FOFITOS';viewerUsername.textContent=doctor?'@iamdoctorfarmer':'FOFITOS';viewerAppointment.hidden=!doctor;viewerCaptionAvatar.hidden=!doctor;viewer.classList.toggle('fofitos-view',!doctor);document.querySelector('.prev').hidden=false;document.querySelector('.next').hidden=false}
function showViewerFromTop(){viewer.scrollTop=0;viewer.scrollLeft=0;document.querySelector('.insta-caption').scrollTop=0;if(!viewer.open)viewer.showModal();requestAnimationFrame(()=>{viewer.scrollTop=0;viewer.scrollLeft=0;document.querySelector('.insta-caption').scrollTop=0})}
function captionEmojis(message){const text=message.toLowerCase();if(/morning|begin|start|new day/.test(text))return'🌅✨';if(/rest|recover|sleep|pause|energy/.test(text))return'😴🔋';if(/calm|quiet|still|peace|clarity|mindful/.test(text))return'🧘‍♂️🌿';if(/walk|move|step|climb|forward|journey|path/.test(text))return'🚶‍♂️🏔️';if(/food|meal|nourish|nutrition/.test(text))return'🥗🌱';if(/strength|strong|body|fitness|workout/.test(text))return'💪🔥';if(/courage|fear|uncertain|unknown/.test(text))return'🦁🔥';if(/balance|steady|pace|rhythm/.test(text))return'⚖️🌿';if(/heal|health|wellbeing|care/.test(text))return'❤️‍🩹✨';if(/grow|build|habit|foundation|future/.test(text))return'🌱🧱';if(/discipline|consistent|effort|commit/.test(text))return'🎯💪';return'✨💪'}
function doctorCaption(index=current){const message=captions[index].replace(/\n\n#[\s\S]*$/,'').trim();return `${captionEmojis(message)} ${message}\n\n${doctorHashtags}`}
function openViewer(i){viewerMode='doctor';setViewerBrand(viewerMode);current=i;const p=posters[i],d=dateFor(i);viewerImage.src=p.src;viewerImage.alt=`Motivational poster at ${p.title}`;viewerTitle.textContent=`Post ${String(i+1).padStart(2,'0')} of ${posters.length}`;viewerCount.textContent=`${posters.length}-day health series`;viewerCaption.textContent=doctorCaption(i);viewerLocation.textContent=p.title;viewerDate.textContent=dayFmt.format(d).toUpperCase();copyCaptionButton.classList.remove('copied');copyCaptionButton.lastChild.textContent=' Copy + download';showViewerFromTop()}
function openFofitosViewer(i=0){viewerMode='fofitos';setViewerBrand(viewerMode);current=i;const p=fofitosPosts[i],d=new Date(`${p.date}T12:00:00`);viewerImage.src=p.src;viewerImage.alt=`Fofitos ${p.title} nutrition poster`;viewerTitle.textContent=`Post ${String(i+1).padStart(2,'0')} of ${fofitosPosts.length}`;viewerCount.textContent='Fofitos daily food series';viewerCaption.textContent=fofitosCaptions[i];viewerLocation.textContent=p.title;viewerDate.textContent=dayFmt.format(d).toUpperCase();copyCaptionButton.classList.remove('copied');copyCaptionButton.lastChild.textContent=' Copy + download';showViewerFromTop()}
function move(dir){if(viewerMode==='fofitos'){current=(current+dir+fofitosPosts.length)%fofitosPosts.length;openFofitosViewer(current);return}const pos=visible.indexOf(current);current=visible[(pos+dir+visible.length)%visible.length];openViewer(current)}
