function fofitosMonthPosts(monthDate){return fofitosPosts.map((post,index)=>({post,index})).filter(({post})=>{const date=new Date(`${post.date}T12:00:00`);return date.getFullYear()===monthDate.getFullYear()&&date.getMonth()===monthDate.getMonth()})}
function renderEmptyMonths(isFofitos=false){emptyMonthGrid.innerHTML='';Array.from({length:12},(_,i)=>new Date(2026,7+i,1)).forEach(date=>{const entries=isFofitos?fofitosMonthPosts(date):[],ready=entries.length>0,month=document.createElement('button'),label=date.toLocaleDateString('en-IN',{month:'long',year:'numeric'});month.type='button';month.className=`month-card${ready?'':' pending'}`;month.disabled=!ready;month.innerHTML=ready?`<img src="${entries[0].post.src}" alt=""><span class="month-card-shade"></span><span class="month-card-copy"><small>READY · ${entries.length} POSTS</small><strong>${label}</strong><em>Open collection →</em></span>`:`<span class="month-card-empty">+</span><span class="month-card-copy"><small>AWAITING POSTERS · 0/30</small><strong>${label}</strong><em>Next monthly collection</em></span>`;if(ready)month.addEventListener('click',()=>{document.querySelectorAll('#empty-month-grid .month-card').forEach(card=>card.classList.remove('active'));month.classList.add('active');renderFofitosReady(entries);channelReady.hidden=false;channelReady.scrollIntoView({behavior:'smooth'})});emptyMonthGrid.append(month)})}
function renderFofitosReady(entries=fofitosMonthPosts(new Date(2026,7,1))){const firstDate=new Date(`${entries[0].post.date}T12:00:00`),lastDate=new Date(`${entries.at(-1).post.date}T12:00:00`),monthLabel=firstDate.toLocaleDateString('en-IN',{month:'long',year:'numeric'});document.querySelector('#channel-ready-title').textContent=monthLabel;document.querySelector('#channel-ready .schedule-bar p strong').textContent=`${rangeFmt.format(firstDate)} — ${rangeFmt.format(lastDate)}`;document.querySelector('#channel-ready .schedule-bar p span').textContent=`${entries.length} Instagram posts scheduled`;document.querySelector('#channel-ready .filter span').textContent=entries.length;channelReadyGrid.classList.add('schedule-view');channelReadyGrid.innerHTML=`<div class="grid fofitos-schedule">${entries.map(({post,index})=>{const d=new Date(`${post.date}T12:00:00`);return `<article class="card"><button class="poster-button" data-fofitos-view="${index}" aria-label="View ${post.title} poster scheduled for ${dayFmt.format(d)}"><span class="date-badge"><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('en-IN',{weekday:'short'}).toUpperCase()}</span></span><img src="${post.src}" alt="Fofitos ${post.title} food poster" loading="lazy"></button><button class="card-copy" type="button" data-fofitos-copy="${index}" aria-label="Copy caption and download ${post.title} poster"><span aria-hidden="true">⇩</span> Download + copy</button><div class="meta"><span class="num">${String(index+1).padStart(2,'0')}</span><div><h3>${post.title}</h3><p>${dayFmt.format(d)} · Fofitos</p></div></div></article>`}).join('')}</div>`;channelReadyGrid.querySelectorAll('[data-fofitos-view]').forEach(button=>button.addEventListener('click',()=>openFofitosViewer(Number(button.dataset.fofitosView))));channelReadyGrid.querySelectorAll('[data-fofitos-copy]').forEach(button=>button.addEventListener('click',event=>{viewerMode='fofitos';copyCaption(Number(button.dataset.fofitosCopy),event.currentTarget)}))}
async function copyTextValue(text,button){let copied=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);copied=true}}catch(error){}if(!copied){const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.cssText='position:fixed;opacity:0;pointer-events:none';document.body.append(area);area.select();copied=document.execCommand('copy');area.remove()}if(!copied){button.textContent='Copy failed';return}button.classList.add('copied');const original=button.textContent;button.textContent='Copied!';setTimeout(()=>{button.classList.remove('copied');button.textContent=original},1800)}
async function downloadMediaAndCopyCaption(item,button){const original=button.textContent;button.disabled=true;button.textContent='Preparing downloads…';let imageStarted=false,videoStarted=false,copied=false;try{const imageLink=document.createElement('a');imageLink.href=item.image;imageLink.download=item.image.split('/').pop().split('?')[0];document.body.append(imageLink);imageLink.click();imageLink.remove();imageStarted=true}catch(error){}try{const videoLink=document.createElement('a');videoLink.href=item.video;videoLink.target='_blank';videoLink.rel='noopener';document.body.append(videoLink);videoLink.click();videoLink.remove();videoStarted=true}catch(error){}try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(item.caption);copied=true}}catch(error){}if(!copied){const area=document.createElement('textarea');area.value=item.caption;area.setAttribute('readonly','');area.style.cssText='position:fixed;opacity:0;pointer-events:none';document.body.append(area);area.select();copied=document.execCommand('copy');area.remove()}const complete=imageStarted&&videoStarted&&copied;button.classList.toggle('copied',complete);button.textContent=complete?'Image + video downloaded · caption copied!':copied?'Caption copied · check downloads':'Downloads started · copy blocked';setTimeout(()=>{button.classList.remove('copied');button.disabled=false;button.textContent=original},2800)}
function renderVideoCarousels(){videoCarouselGrid.innerHTML=doctorVideoCarousels.map((item,index)=>`<article class="video-carousel-entry"><figure class="video-carousel-cover"><img src="${item.image}" alt="${item.title} award ceremony cover"><figcaption><strong>${item.title}</strong><small>Source: ${item.source}</small></figcaption></figure><div class="video-caption-stack"><section class="caption-panel"><div class="caption-panel-head"><strong>Instagram caption</strong><button class="caption-copy caption-download-copy" type="button" data-caption-copy="${index}">Download image + video + copy caption</button></div><p class="caption-text">${item.caption}</p></section><section class="caption-panel"><div class="caption-panel-head"><strong>Video Captions</strong></div><div class="video-caption-options">${item.videoCaptions.map((caption,option)=>`<div class="video-caption-option"><div class="video-caption-option-head"><small>Option ${option+1}</small><button class="caption-copy" type="button" data-video-copy="${index}" data-video-option="${option}">Copy option ${option+1}</button></div><p class="caption-text video-short">${caption}</p></div>`).join('')}</div></section></div></article>`).join('');videoCarouselGrid.querySelectorAll('[data-caption-copy]').forEach(button=>button.addEventListener('click',()=>downloadMediaAndCopyCaption(doctorVideoCarousels[Number(button.dataset.captionCopy)],button)));videoCarouselGrid.querySelectorAll('[data-video-copy]').forEach(button=>button.addEventListener('click',()=>copyTextValue(doctorVideoCarousels[Number(button.dataset.videoCopy)].videoCaptions[Number(button.dataset.videoOption)],button)))}
function routeChannel(){
 const route=location.hash.slice(1)||'channels',match=route.match(/^(doctor-farmer|fofitos|longer-life)(?:-(posts|reels|carousels|video-carousel))?$/),brandKey=match?.[1],format=match?.[2],brandName=brandKey==='doctor-farmer'?'Doctor Farmer':brandKey==='fofitos'?'FOFITOS':'Longer Life Wellness';
 channelDashboard.hidden=route!=='channels';contentTypePage.hidden=!(brandKey&&!format);channelWorkspace.hidden=route!=='doctor-farmer-posts';emptyChannel.hidden=route!=='fofitos-posts'&&route!=='longer-life-posts';videoCarouselPage.hidden=route!=='doctor-farmer-video-carousel';formatEmptyPage.hidden=!(['reels','carousels'].includes(format)||(format==='video-carousel'&&brandKey!=='doctor-farmer'));
 if(brandKey&&!format){contentTypeTitle.textContent=brandName;document.querySelector('#content-type-posts').href=`#${brandKey}-posts`;document.querySelector('#content-type-reels').href=`#${brandKey}-reels`;document.querySelector('#content-type-carousels').href=`#${brandKey}-carousels`;document.querySelector('#content-type-video-carousel').href=`#${brandKey}-video-carousel`;requestAnimationFrame(()=>contentTypePage.scrollIntoView())}
 else if(route==='doctor-farmer-posts'){collectionContent.hidden=true;startInput.value='';document.querySelector('#selected-month').textContent='';renderMonthCards();requestAnimationFrame(()=>channelWorkspace.scrollIntoView())}
 else if(route==='fofitos-posts'||route==='longer-life-posts'){const isFofitos=route==='fofitos-posts';document.querySelector('#posts-back').href=isFofitos?'#fofitos':'#longer-life';emptyChannelTitle.innerHTML=isFofitos?'REAL FOOD.<br>REAL STORIES.':'LONGER LIFE';emptyChannelNote.textContent=isFofitos?`${fofitosPosts.length} edited Fofitos posters are scheduled from 25 August, each with its own caption and download action.`:'No posts have been added to this channel yet.';channelReady.hidden=true;if(isFofitos)renderFofitosReady();renderEmptyMonths(isFofitos);requestAnimationFrame(()=>emptyChannel.scrollIntoView())}
 else if(route==='doctor-farmer-video-carousel'){renderVideoCarousels();requestAnimationFrame(()=>videoCarouselPage.scrollIntoView())}
 else if(['reels','carousels','video-carousel'].includes(format)){formatBrand.textContent=brandName;formatEmptyTitle.textContent=format==='video-carousel'?'VIDEO CAROUSEL':format.toUpperCase();formatBack.href=`#${brandKey}`;requestAnimationFrame(()=>formatEmptyPage.scrollIntoView())}
 else if(route!=='channels')history.replaceState(null,'',location.pathname+location.search+'#channels')
}
window.addEventListener('hashchange',routeChannel);startInput.value='';document.querySelector('#selected-month').textContent='';renderMonthCards();routeChannel();
